import type {
  CrosshairInk,
  CrosshairLineStyle,
  CrosshairTargetEffect,
} from './types';

export const LINE_STYLES: CrosshairLineStyle[] = ['solid', 'dashed', 'dotted'];
export const EFFECTS: CrosshairTargetEffect[] = ['lock', 'glitch', 'none'];
export const FONT =
  '500 10px ui-monospace, SFMono-Regular, Menlo, Consolas, monospace';
export const HIDDEN = 'crosshair-cursor-hidden';

export function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

/** Resolves any CSS color to RGBA through the canvas color parser. */
export function toRgb(
  ctx: CanvasRenderingContext2D,
  color: string,
): CrosshairInk {
  ctx.fillStyle = '#000';
  ctx.fillStyle = color;
  const value = String(ctx.fillStyle);
  if (value.startsWith('#')) {
    const hex = Number.parseInt(value.slice(1, 7), 16);
    return { r: (hex >> 16) & 255, g: (hex >> 8) & 255, b: hex & 255, a: 1 };
  }
  const parts = value.match(/[\d.]+/g)?.map(Number) ?? [255, 255, 255, 1];
  return {
    r: parts[0] ?? 255,
    g: parts[1] ?? 255,
    b: parts[2] ?? 255,
    a: parts[3] ?? 1,
  };
}

export { default as Crosshair } from './Crosshair.vue';
export type {
  CrosshairBlendMode,
  CrosshairLineStyle,
  CrosshairProps,
  CrosshairTargetEffect,
} from './types';

export type CrosshairLineStyle = 'solid' | 'dashed' | 'dotted';
export type CrosshairTargetEffect = 'lock' | 'glitch' | 'none';
export type CrosshairBlendMode = 'normal' | 'difference';

export interface CrosshairProps {
  /** Color of the lines, labels and brackets. */
  color?: string;
  /**
   * Keeps the crosshair inside this element (needs a non-static position).
   * Without it the crosshair covers the whole viewport.
   */
  container?: HTMLElement | null;
  /** Line thickness in px. */
  thickness?: number;
  /** Opacity of everything the crosshair draws. */
  opacity?: number;
  lineStyle?: CrosshairLineStyle;
  /** Empty space in px left around the pointer where the lines would cross. */
  gap?: number;
  /** How much the lines fade out toward the edges, 0–1. */
  fade?: number;
  /** How far the lines trail behind the pointer. 0 sticks to it. */
  smoothing?: number;
  /** Pointer position where the lines meet the edges, and locked-target size. */
  showCoordinates?: boolean;
  targetEffect?: CrosshairTargetEffect;
  /** CSS selector for the elements the crosshair reacts to. */
  targetSelector?: string;
  /** Ring out from the pointer on every click or tap. */
  clickPulse?: boolean;
  /** Hides the system cursor inside the area and draws a dot instead. */
  hideCursor?: boolean;
  blendMode?: CrosshairBlendMode;
  class?: string;
}

export interface CrosshairInk {
  r: number;
  g: number;
  b: number;
  a: number;
}

export interface CrosshairPulse {
  x: number;
  y: number;
  age: number;
}

export interface CrosshairBox {
  x: number;
  y: number;
  w: number;
  h: number;
}

export interface CrosshairSettings {
  color: string;
  thickness: number;
  opacity: number;
  lineStyle: CrosshairLineStyle;
  gap: number;
  fade: number;
  smoothing: number;
  showCoordinates: boolean;
  targetEffect: CrosshairTargetEffect;
  targetSelector: string;
  clickPulse: boolean;
  hideCursor: boolean;
}
